result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/terrain_dijkstra.py", "content": """"Weighted-terrain Dijkstra over a digit grid.

Entering a cell costs the value of its digit. Movement is 4-connected.
"""

import heapq

DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))


def parse_terrain(text):
    """Parse a block of digit rows into a list of list of ints."""
    return [[int(ch) for ch in line.strip()] for line in text.strip().splitlines()]


def dijkstra(grid, start, goal):
    """Cheapest path on `grid` from `start` to `goal` (4-connected).

    Cost of a move = terrain value of the destination cell.
    Returns (total_cost, path) where path includes both endpoints.
    Raises ValueError if unreachable or endpoints out of bounds.
    """
    rows, cols = len(grid), len(grid[0])
    for r, c in (start, goal):
        if not (0 <= r < rows and 0 <= c < cols):
            raise ValueError(f"endpoint {r},{c} out of bounds")

    dist = {start: 0}
    prev = {}
    pq = [(0, start)]
    while pq:
        d, cur = heapq.heappop(pq)
        if d > dist.get(cur, float("inf")):
            continue
        if cur == goal:
            break
        for dr, dc in DIRS:
            nxt = (cur[0] + dr, cur[1] + dc)
            if not (0 <= nxt[0] < rows and 0 <= nxt[1] < cols):
                continue
            nd = d + grid[nxt[0]][nxt[1]]
            if nd < dist.get(nxt, float("inf")):
                dist[nxt] = nd
                prev[nxt] = cur
                heapq.heappush(pq, (nd, nxt))

    if goal not in dist:
        raise ValueError("goal unreachable")

    # Reconstruct path by walking predecessors back from goal.
    path = [goal]
    while path[-1] != start:
        path.append(prev[path[-1]])
    path.reverse()
    return dist[goal], path


def bfs_distance(uniform_grid, start, goal):
    """Reference BFS hop count on a grid (for the degenerate-case test)."""
    rows, cols = len(uniform_grid), len(uniform_grid[0])
    frontier, seen = [start], {start}
    hops = 0
    while frontier:
        nxt = []
        for cell in frontier:
            if cell == goal:
                return hops
            r, c = cell
            for dr, dc in DIRS:
                nb = (r + dr, c + dc)
                if 0 <= nb[0] < rows and 0 <= nb[1] < cols and nb not in seen:
                    seen.add(nb)
                    nxt.append(nb)
        frontier = nxt
        hops += 1
    return float("inf")
